@once
@push('styles')
<style>
.daily-review-pagination{display:flex!important;align-items:center;justify-content:space-between;gap:14px;min-height:62px;padding:13px 17px!important;border-top:1px solid #dfe9ef!important;background:linear-gradient(180deg,#fbfdfe,#f5f9fb)!important;color:#6a8191}.daily-review-pagination>.text-muted,.daily-pagination-summary{display:flex;align-items:center;min-height:34px;color:#667f90!important;font-size:13px}.daily-review-pagination>.text-muted:before,.daily-pagination-summary:before{content:"\f03a";display:inline-flex;width:30px;height:30px;align-items:center;justify-content:center;margin-right:8px;border-radius:8px;background:#e6f2f9;color:#2d86b5;font-family:FontAwesome}.daily-review-pagination .pagination{display:flex;align-items:center;gap:5px;margin:0!important;padding:0;white-space:nowrap}.daily-review-pagination .pagination>li{display:block}.daily-review-pagination .pagination>li>a,.daily-review-pagination .pagination>li>span{display:flex;min-width:35px;height:35px;align-items:center;justify-content:center;padding:0 10px;border:1px solid #d4e2ea!important;border-radius:7px!important;background:#fff;color:#397b9f;font-weight:600;line-height:1;box-shadow:0 2px 5px rgba(42,83,108,.06);transition:.15s}.daily-review-pagination .pagination>li>a:hover{border-color:#3d97c5!important;background:#eef8fd;color:#1d719d;transform:translateY(-1px)}.daily-review-pagination .pagination>.active>a,.daily-review-pagination .pagination>.active>span{border-color:#2e88b8!important;background:linear-gradient(135deg,#3c9dcc,#247cac)!important;color:#fff!important;box-shadow:0 4px 10px rgba(44,134,182,.24)}.daily-review-pagination .pagination>.disabled>span,.daily-review-pagination .pagination>.disabled>a{border-color:#e2e8ec!important;background:#f1f4f6!important;color:#a7b4bd!important;box-shadow:none}.daily-review-pagination .pull-right{float:none!important;margin-left:auto}@media(max-width:767px){.daily-review-pagination{align-items:flex-start;flex-direction:column}.daily-review-pagination .pull-right,.daily-review-pagination .pagination{max-width:100%;margin-left:0!important;overflow-x:auto;padding-bottom:3px}}
</style>
@endpush
@push('scripts')
<script>
(function(){function item(label,href,state){var li=document.createElement('li');if(state)li.className=state;var node=document.createElement(href?'a':'span');node.textContent=label;if(href)node.href=href;li.appendChild(node);return li;}document.querySelectorAll('.content .box-footer').forEach(function(footer){var existing=footer.querySelector('.pagination'),nav=footer.querySelector('nav[role="navigation"]');if(!existing&&!nav)return;footer.classList.add('daily-review-pagination');if(existing)return;var activeNode=nav.querySelector('[aria-current="page"]'),current=activeNode?parseInt(activeNode.textContent.trim(),10)||1:1,links=Array.prototype.slice.call(nav.querySelectorAll('a')),pages={},previous='',next='';links.forEach(function(link){var rel=link.getAttribute('rel'),label=(link.getAttribute('aria-label')||link.textContent||'').trim(),match=label.match(/(?:page|第)\s*(\d+)/i)||link.textContent.trim().match(/^(\d+)$/);if(rel==='prev')previous=link.href;else if(rel==='next')next=link.href;else if(match)pages[parseInt(match[1],10)]=link.href;});pages[current]=pages[current]||'';var numbers=Object.keys(pages).map(Number).filter(Boolean).sort(function(a,b){return a-b;}),ul=document.createElement('ul');ul.className='pagination pagination-sm';ul.appendChild(item('‹ 上一页',previous,previous?'':'disabled'));numbers.forEach(function(page){ul.appendChild(item(String(page),page===current?'':pages[page],page===current?'active':''));});ul.appendChild(item('下一页 ›',next,next?'':'disabled'));var summary=footer.querySelector('.text-muted');if(!summary){summary=document.createElement('span');summary.className='daily-pagination-summary';var totalText=(nav.textContent||'').replace(/\s+/g,' '),range=totalText.match(/(?:Showing|显示)\s*(\d+)\s*(?:to|至|到)\s*(\d+).*?(?:of|共)\s*(\d+)/i);summary.textContent=range?'显示 '+range[1]+'-'+range[2]+' 条，共 '+range[3]+' 条':'当前第 '+current+' 页';footer.insertBefore(summary,footer.firstChild);}nav.replaceWith(ul);});})();
</script>
@endpush
@endonce
